To see the impact, wrote a quick test to show the current state.

{code}
@Test
    public void test()
    {
        Field[] fields = Config.class.getDeclaredFields();
        Method[] methods = DatabaseDescriptor.class.getDeclaredMethods();
        long empty = 0, immutable = 0, mutable = 0;
        for (Field field : fields)
        {
            if (Modifier.isStatic(field.getModifiers())) continue;
            String name = FBUtilities.snakeToCamel(field.getName());
            name = name.substring(0, 1).toUpperCase() + name.substring(1);
            String getter = "get" + name;
            String setter = "set" + name;

            long numGetters = Stream.of(methods).filter(m -> m.getName().equals(getter)).count();
            long numSetters = Stream.of(methods).filter(m -> m.getName().equals(setter)).count();
            if (numGetters == 0)
            {
                System.out.println("No getter found for " + name);
                empty++;
            }
            else if (numSetters == 0)
            {
                System.out.println("Immutable " + name);
                immutable++;
            }
            else
            {
                System.out.println("Mutable " + name);
                mutable++;
            }
        }
        double total = empty + mutable + immutable;
        System.out.println("Empty configs: " + empty + "(" + (empty / total * 100) + "%)");
        System.out.println("Immutable configs: " + empty + "(" + (immutable / total * 100) + "%)");
        System.out.println("Mutable configs: " + empty + "(" + (mutable / total * 100) + "%)");
    }
{code}

